const I = ({ d, s = 20, fill = "none", w = 1.9, style }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={fill} stroke="currentColor"
    strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" style={style}>{d}</svg>
);

const Ic = {
